package com.example.remoteportal.service;

import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class WorksheetCalculatorService {
  private static final int[] STD={15,20,25,30,35,40,45,50,60,70,80,90,100,110,125,150,175,200,225,250,300,350,400,450,500,600,700,800,1000,1200,1600,2000,2500,3000,4000,5000,6000};
  public Map<String,Object> dryTransformer(double kva,double pv,double sv,int phases){positive(kva,"kVA");positive(pv,"Primary voltage");positive(sv,"Secondary voltage");phase(phases);double ip=current(kva*1000,pv,phases),is=current(kva*1000,sv,phases),p125=ip*1.25;int pMax=nextUp(p125),pAlt=nextDown(p125);double s125=is*1.25;LinkedHashMap<String,Object> r=new LinkedHashMap<>();r.put("edition","CEC_2024");r.put("calculator","DRY_TYPE_TRANSFORMER_WORKSHEET");r.put("primaryCurrentA",round(ip));r.put("primary125A",round(p125));r.put("primaryMaximumCommonOcpdA",pMax);r.put("primaryAlternateCommonOcpdA",pAlt);r.put("primaryConductorAmpacityMaxMethodA",round(pMax));r.put("primaryConductorAmpacityAlternateMethodA",round(p125));r.put("secondaryCurrentA",round(is));r.put("secondaryConductorAmpacityMaxMethodA",round(pMax*(pv/sv)));r.put("secondaryConductorAmpacityAlternateMethodA",round(s125));r.put("secondary125A",round(s125));r.put("secondaryCommonOcpdA",nextDown(s125));r.put("ratio",round(pv/sv));r.put("reference","CEC 2024 Rules 26-254 and 26-256; Table 13 common sizes.");r.put("note","Reports required ampacities rather than inventing conductor/raceway sizes where the validated table dataset is not yet loaded.");return r;}
  public Map<String,Object> hvTransformer(double mva,double pvKv,double svKv,String protection,double protectionFactor,String material,String wiringMethod,String voltageClass){positive(mva,"MVA");positive(pvKv,"Primary kV");positive(svKv,"Secondary kV");factor(protectionFactor,"Protection factor");double ip=mva*1_000_000/(pvKv*1000*Math.sqrt(3)),is=mva*1_000_000/(svKv*1000*Math.sqrt(3)),pCalc=ip*protectionFactor;int pProt="FUSE".equalsIgnoreCase(protection)?nextUp(pCalc):nextDown(pCalc);double p125=ip*1.25,pReq=Math.max(p125,pProt),s125=is*1.25,sRatio=pProt*(pvKv/svKv),sReq=Math.max(s125,sRatio);LinkedHashMap<String,Object> r=new LinkedHashMap<>();r.put("edition","CEC_2024");r.put("calculator","HV_TRANSFORMER_WORKSHEET");r.put("primaryCurrentA",round(ip));r.put("primaryProtectionCalculatedA",round(pCalc));r.put("primaryProtectionCommonA",pProt);r.put("primary125AmpacityA",round(p125));r.put("primaryRequiredAmpacityAfterOcpdCheckA",round(pReq));r.put("secondaryCurrentA",round(is));r.put("secondary125AmpacityA",round(s125));r.put("secondaryOcpdRatioMinimumA",round(sRatio));r.put("secondaryRequiredAmpacityA",round(sReq));r.put("voltageRatio",round(pvKv/svKv));r.put("tableFamilyHint",tableHint(voltageClass,material,wiringMethod));r.put("reference","CEC 2024 Rules 26-250 and 26-256, including 26-256(4), plus the applicable D17 cable table.");r.put("note","Protection factor remains visible because the applicable rule/protection arrangement must be confirmed.");return r;}
  public Map<String,Object> capacitorKvar(double kvar,double voltage,int phases){positive(kvar,"kVAR");positive(voltage,"Voltage");phase(phases);double fla=phases==3?kvar*1000/(voltage*Math.sqrt(3)):kvar*1000/voltage,cond=fla*1.35,ocpdCalc=fla*2.5,disc=fla*1.35;LinkedHashMap<String,Object> r=new LinkedHashMap<>();r.put("edition","CEC_2024");r.put("calculator","CAPACITOR_WORKSHEET");r.put("flaA",round(fla));r.put("conductorAmpacityA",round(cond));r.put("ocpdCalculatedA",round(ocpdCalc));r.put("maximumCommonOcpdA",nextDown(ocpdCalc));r.put("disconnectCalculatedA",round(disc));r.put("minimumCommonNonFusedDisconnectA",nextUp(disc));r.put("reference","CEC 2024 Rules 26-208(1), 26-210 and 26-214; Table 13 common sizes.");r.put("note","If the disconnect is fusible, its physical rating must accommodate the selected fuses.");return r;}
  public Map<String,Object> refrigeration(double rla,Double lra){positive(rla,"RLA");double locked=(lra!=null&&lra>0)?lra:rla*6;double cond=rla*1.25,ocpdNormal=locked*0.50,ocpdStart=locked*0.65,relay=rla*1.40,fuse=rla*1.25;LinkedHashMap<String,Object> r=new LinkedHashMap<>();r.put("edition","CEC_2024");r.put("calculator","REFRIGERATION_WORKSHEET");r.put("rlaA",round(rla));r.put("lraA",round(locked));r.put("lraWasDerived",lra==null||lra<=0);r.put("conductorAmpacityA",round(cond));r.put("normalOcpdCalculatedA",round(ocpdNormal));r.put("normalCommonOcpdA",nextDown(ocpdNormal));r.put("notStartingOcpdCalculatedA",round(ocpdStart));r.put("notStartingCommonOcpdA",nextDown(ocpdStart));r.put("relayOverloadA",round(relay));r.put("fuseOverloadA",round(fuse));r.put("reference","Worksheet flow based on uploaded hermetic refrigerant motor exercises.");r.put("note","Use nameplate RLA/LRA where provided; examples derive LRA as 6 × RLA when needed.");return r;}
  public Map<String,Object> welder(double kva,double voltage,double ratedPrimaryCurrentA,double dutyFactor,String type,double selectedConductorAmpacity){factor(dutyFactor,"Duty-cycle factor");boolean motorGenerator="MOTOR_GENERATOR".equalsIgnoreCase(type);boolean resistance="RESISTANCE".equalsIgnoreCase(type);double input;if(motorGenerator){positive(ratedPrimaryCurrentA,"Rated primary current");input=ratedPrimaryCurrentA;}else{positive(kva,"kVA");positive(voltage,"Voltage");input=kva*1000/voltage;}double effective=input*dutyFactor;LinkedHashMap<String,Object> r=new LinkedHashMap<>();r.put("edition","CEC_2024");r.put("calculator","WELDER_WORKSHEET");r.put("welderType",motorGenerator?"MOTOR_GENERATOR_ARC":resistance?"RESISTANCE":"TRANSFORMER_INVERTER_ARC");r.put("inputCurrentA",round(input));r.put("dutyAdjustedConductorLoadA",round(effective));r.put("dutyTable",motorGenerator?"42B":resistance?"42C":"42A");r.put("selectedConductorAmpacityA",round(selectedConductorAmpacity));if(motorGenerator){r.put("protectionMethod","Use Section 28 motor overcurrent, overload, controller and disconnect rules; Rule 42-012 routes motor-generator welders through Sections 4 and 28.");r.put("reference","CEC 2024 Rule 42-012 and Table 42B; Sections 4 and 28 for protection/control.");r.put("note","Motor-generator arc welders use rated primary current in amperes. The 200% transformer-arc and 300% resistance-welder shortcuts are not applied to this type.");return r;}double mult=resistance?3.0:2.0,sub1=input*mult,sub2=selectedConductorAmpacity>0?selectedConductorAmpacity*mult:0;int common1=nextDown(sub1),common2=selectedConductorAmpacity>0?nextUp(sub2):0,outcome=selectedConductorAmpacity>0?Math.min(common1,common2):common1;r.put("ocpdMultiplier",mult);r.put("subrule1CalculatedA",round(sub1));r.put("subrule1CommonA",common1);r.put("subrule2CalculatedA",round(sub2));r.put("subrule2CommonA",common2);r.put("startingOutcomeA",outcome);r.put("reference",resistance?"CEC 2024 Rules 42-014 and 42-016; Table 42C.":"CEC 2024 Rules 42-006 and 42-008; Table 42A.");r.put("note",resistance?"Resistance-welder worksheet uses the selected Table 42C duty factor and the 300% overcurrent limits.":"Transformer/inverter arc-welder worksheet uses the selected Table 42A duty factor and the 200% overcurrent limits.");return r;}
  private static String tableHint(String v,String m,String w){v=v==null?"":v.toUpperCase();m=m==null?"":m.toUpperCase();w=w==null?"":w.toUpperCase();if(v.contains("25-46")&&m.contains("COPPER")&&w.contains("BURIED"))return "Table D17G";if(v.contains("5-15")&&m.contains("ALUMINUM")&&w.contains("OUTDOOR"))return "Table D17N";return "Select applicable CEC D17 table";}
  private static double current(double va,double v,int p){return p==3?va/(v*Math.sqrt(3)):va/v;} private static int nextUp(double a){for(int x:STD)if(x>=a)return x;return(int)Math.ceil(a);} private static int nextDown(double a){int last=STD[0];for(int x:STD){if(x>a)break;last=x;}return last;} private static void positive(double v,String n){if(v<=0)throw new IllegalArgumentException(n+" must be greater than zero");} private static void phase(int p){if(p!=1&&p!=3)throw new IllegalArgumentException("Phases must be 1 or 3");} private static void factor(double v,String n){if(v<=0||v>5)throw new IllegalArgumentException(n+" invalid");} private static double round(double v){return Math.round(v*100.0)/100.0;}
}
